using System.Net;
using Lou.Core;
using Lou.Providers;
using Lou.Rendering;
using SkiaSharp;
using Xunit;
namespace Lou.Tests;
public sealed class UniversalTests
{
    [Fact]public void Hardware_control_settings_are_never_restored(){var s=new ReadOnlyHardwareSettings();s.SetValue("/gpu/control/mode","2");Assert.False(s.Contains("/gpu/control/mode"));Assert.Equal(((int)LibreHardwareMonitor.Hardware.ControlMode.Undefined).ToString(),s.GetValue("/gpu/control/mode","2"));}
    [Fact]public void Physical_gpu_replacement_invalidates_existing_selection(){var now=DateTimeOffset.UtcNow;var sensor=new HardwareReading("/gpu/temp","Same model","GpuNvidia","GPU Core","Temperature",60,"/gpu",DeviceId:"PCI-new");var data=new HardwareSnapshot(now,"active",[sensor],"board");Assert.Null(SensorCatalog.Enrich(new(),data,new(){GpuController="/gpu",GpuHardware="Same model",GpuDeviceId="PCI-old"},now).GpuTemp);}
    [Fact] public void Clean_defaults_have_no_personal_configuration(){var s=new Settings();Assert.Empty(s.Displays);Assert.Empty(s.FanBindings);Assert.Empty(s.Location);Assert.False(s.CitySelected);Assert.Equal(5,s.Pages.Count);Assert.All(s.Pages,p=>Assert.True(p.Enabled));Assert.EndsWith(Path.Combine("Data"),ConfigStore.Root);}
    [Fact] public void Single_Aio_has_every_page_and_independent_timing(){var s=new Settings();var aio=new DisplaySettings{InstanceId="square",PreviewWidth=480,PreviewHeight=480,PageIntervalSeconds=30,UsbFps=10};var large=new DisplaySettings{InstanceId="wide",PageIntervalSeconds=12,UsbFps=24};s.Displays=[aio,large];var a=s.ForDisplay(aio);var b=s.ForDisplay(large);Assert.Equal((480,480,30,10),(a.Width,a.Height,a.PageIntervalSeconds,a.UsbFps));Assert.Equal((1920,462,12,24),(b.Width,b.Height,b.PageIntervalSeconds,b.UsbFps));a.Pages[0].Enabled=false;Assert.True(b.Pages[0].Enabled);Assert.True(s.Displays[0].Pages[0].Enabled);}
    [Theory][InlineData(0,1920,462)][InlineData(90,462,1920)][InlineData(180,1920,462)][InlineData(270,462,1920)]public void Orientation_changes_logical_layout(int rotation,int width,int height){var d=new DisplaySettings{InstanceId="id",Profile=new("id",1920,462,65,5,180),Rotation=rotation};var s=new Settings().ForDisplay(d);Assert.Equal((width,height),(s.Width,s.Height));}
    [Fact]public void Different_screens_rotate_independently(){var a=new DisplaySettings{PageIntervalSeconds=10};var b=new DisplaySettings{PageIntervalSeconds=30};var first=new PageScheduler();var second=new PageScheduler();var t=DateTimeOffset.UtcNow;first.Select(a,Snapshot.Empty,t);second.Select(b,Snapshot.Empty,t);Assert.Equal(PageId.Weather,first.Select(a,Snapshot.Empty,t.AddSeconds(11)));Assert.Equal(PageId.System,second.Select(b,Snapshot.Empty,t.AddSeconds(11)));}
    [Fact]public void Export_import_preserves_user_associations_and_no_fixed_profile_replaces_them(){var s=new Settings{Displays=[new(){InstanceId="custom",PreviewWidth=480,PreviewHeight=480}],FanBindings=[new(FanRole.Pump,"LibreHardwareMonitor","Another board","/controller","/fan/3","PUMP",Hardware:"ITE",Topology:"fingerprint")],FanLabels=new(){[FanRole.Pump]="Ma pompe"},CitySelected=true,Location="Paris · France",Latitude=48.8,Longitude=2.3};string file=Path.Combine(Path.GetTempPath(),"lou-portable-"+Guid.NewGuid(),"settings.json");ConfigStore.Save(s,file);var restored=ConfigStore.Load(file);Assert.Equal(s.FanBindings,restored.FanBindings);Assert.Equal("Ma pompe",restored.FanLabels[FanRole.Pump]);Assert.Equal("custom",restored.Displays[0].InstanceId);Assert.Equal("Paris · France",restored.Location);}
    [Fact]public void Inventory_fingerprint_ignores_rpm_and_order_but_detects_hardware_change(){var r=new HardwareReading("/fan/1","ITE","SuperIO","Fan 1","Fan",1000,"/ite");var g=new HardwareReading("/gpu/0/temp","NVIDIA RTX","GpuNvidia","GPU Core","Temperature",42,"/gpu/0");Assert.Equal(SensorCatalog.Topology([r,g]),SensorCatalog.Topology([g with{Value=60},r with{Value=2300}]));Assert.NotEqual(SensorCatalog.Topology([r,g]),SensorCatalog.Topology([r,g with{Hardware="Other GPU"}]));}
    [Fact]public void Changed_inventory_does_not_rebind_a_pump_silently(){var now=DateTimeOffset.UtcNow;var r=new HardwareReading("/fan/1","ITE","SuperIO","Fan 1","Fan",1000,"/ite");var binding=new FanBinding(FanRole.Pump,"LibreHardwareMonitor","board","/ite","/fan/1","PUMP",Hardware:"ITE",Topology:"old");var data=new HardwareSnapshot(now,"active",[r],"board",Topology:"new");Assert.Null(HardwareSensors.EnrichMapped(new(),data,now,[binding]).Pump);}
    [Theory][InlineData("GpuNvidia")][InlineData("GpuAmd")][InlineData("GpuIntel")]public void Gpu_temperature_and_actual_fan_rpm_are_vendor_independent(string kind){var now=DateTimeOffset.UtcNow;var temp=new HardwareReading("/gpu/temp","Card",kind,"GPU Core","Temperature",63,"/gpu");var fan=new HardwareReading("/gpu/fan","Card",kind,"GPU Fan","Fan",0,"/gpu");var data=new HardwareSnapshot(now,"active",[temp,fan],"board");var config=new Settings{FanBindings=[new(FanRole.Gpu,"LibreHardwareMonitor","board","/gpu","/gpu/fan","GPU",Hardware:"Card")]};var pc=HardwareSensors.EnrichMapped(new(),data,now,config.FanBindings);pc=SensorCatalog.Enrich(pc,data,config,now);Assert.Equal(63,pc.GpuTemp);Assert.Equal(0,pc.GpuFan);Assert.Null(HardwareSensors.EnrichMapped(new(),data with{Readings=[temp,fan with{Type="Control"}]},now,config.FanBindings).GpuFan);}
    [Fact]public void Multiple_gpus_require_explicit_selection(){var now=DateTimeOffset.UtcNow;var a=new HardwareReading("/gpu1/temp","A","GpuNvidia","GPU Core","Temperature",50,"/gpu1");var b=a with{Id="/gpu2/temp",ControllerId="/gpu2",Hardware="B",Value=70};var data=new HardwareSnapshot(now,"active",[a,b],"board");Assert.Null(SensorCatalog.Enrich(new(GpuTemp:99),data,new(),now).GpuTemp);Assert.Equal(70,SensorCatalog.Enrich(new(),data,new(){GpuController="/gpu2",GpuHardware="B"},now).GpuTemp);Assert.Null(SensorCatalog.Enrich(new(),data,new(){GpuController="/gpu2",GpuHardware="wrong"},now).GpuTemp);}
    [Fact]public void Temperature_override_never_uses_stale_or_wrong_sensor(){var now=DateTimeOffset.UtcNow;var row=new HardwareReading("temp","CPU","Cpu","Package","Temperature",44,"cpu");var data=new HardwareSnapshot(now,"active",[row],"board");var b=new SensorBinding("LibreHardwareMonitor","board","cpu","temp","CPU");Assert.Equal(44,SensorCatalog.Temperature(data,b,now));Assert.Null(SensorCatalog.Temperature(data,b,now.AddSeconds(6)));Assert.Null(SensorCatalog.Temperature(data,b with{ControllerId="other"},now));}
    [Theory][InlineData(480,480)][InlineData(320,240)][InlineData(640,480)][InlineData(1920,462)]public void Every_page_renders_real_and_missing_data_on_each_format(int width,int height){using var renderer=new UniversalRenderer("missing-assets");foreach(var p in Enum.GetValues<PageId>())foreach(var data in new[]{Snapshot.Empty,Snapshot.Simulation()}){using var bitmap=renderer.Render(p,data,new(){Width=width,Height=height,Night=false},DateTime.Now,0);Assert.Equal((width,height),(bitmap.Width,bitmap.Height));Assert.Equal(255,bitmap.GetPixel(width/2,height/2).Alpha);}}
    [Fact]public async Task City_search_encodes_text_returns_disambiguated_results_without_key(){var handler=new CityHandler();using var provider=new CityProvider(handler);var cities=await provider.SearchAsync("Saint & Test",default);Assert.Contains("Saint%20%26%20Test",handler.Uri!.OriginalString);Assert.DoesNotContain("key",handler.Uri.Query);Assert.Equal(2,cities.Length);Assert.NotEqual(cities[0].Label,cities[1].Label);Assert.Contains("France",cities[0].Label);}
    [Fact]public async Task Weather_without_city_makes_no_request(){var handler=new CityHandler();using var p=new WeatherProvider(handler);var data=await p.ReadAsync(new(),default);Assert.Null(handler.Uri);Assert.Null(data.Temperature);Assert.Equal("Non configurée",data.Status);}
    private sealed class CityHandler:HttpMessageHandler{public Uri? Uri;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Uri=request.RequestUri;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("""{"results":[{"id":1,"name":"Paris","country":"France","latitude":48.8,"longitude":2.3},{"id":2,"name":"Paris","country":"États-Unis","latitude":33.6,"longitude":-95.5}]}""")});}}
}
